using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System;
using System.IO;
using System.Linq;
using ConRoi.Investigation.V36;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            if (EditorApplication.isPlaying || EditorApplication.isCompiling)
                throw new Exception("Edit compiled only");
            AssetDatabase.ImportAsset("Assets/Art/InvestigationV36/R102/EVIDENCE.fbx", ImportAssetOptions.ForceUpdate);
            var a = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Art/InvestigationV36/R102/EVIDENCE.fbx");
            var part = a.GetComponentsInChildren<MeshFilter>().Single(f => f.name == "RepairTool");
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            var tool = s.clipTu.GetComponentsInChildren<Transform>().Single(t => t.name == "Tool_in_hand");
            tool.GetComponent<MeshFilter>().sharedMesh = part.sharedMesh;
            tool.GetComponent<Renderer>().sharedMaterials = part.GetComponent<Renderer>().sharedMaterials.Select(m =>
            {
                string path = "Assets/Art/InvestigationV36/R102/Materials/" + m.name + ".mat";
                var mat = AssetDatabase.LoadAssetAtPath<Material>(path);
                if (!mat)
                {
                    mat = new Material(Shader.Find("Universal Render Pipeline/Lit"));
                    mat.name = m.name;
                    mat.color = m.HasProperty("_BaseColor") ? m.GetColor("_BaseColor") : m.color;
                    AssetDatabase.CreateAsset(mat, path);
                }

                return mat;
            }).ToArray();
            tool.localPosition = Vector3.zero;
            tool.localRotation = Quaternion.identity;
            s.stageCamera.transform.localPosition = new Vector3(4.2f, 5.1f, -4.7f);
            s.stageCamera.transform.LookAt(s.stageCamera.transform.parent.TransformPoint(new Vector3(0, 2, 0)));
            s.stageCamera.fieldOfView = 70;
            s.stageCamera.enabled = false;
            s.modelGate.enabled = false;
            s.clipCamera.fieldOfView = 35;
            s.clipRepair.localPosition = new Vector3(.35f, 3.4f, 1.1f);
            foreach (var gate in s.GetComponentsInChildren<ReturnGateMechanism>(true))
                if (gate.wedgeVisual)
                    gate.wedgeVisual.transform.localPosition = new Vector3(1.18f, .04f, -.7f);
            var sc = s.gameObject.scene;
            EditorSceneManager.MarkSceneDirty(sc);
            EditorSceneManager.SaveScene(sc);
            sc = EditorSceneManager.OpenScene(sc.path);
            int missing = sc.GetRootGameObjects().SelectMany(g => g.GetComponentsInChildren<Transform>(true)).Sum(t => GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject));
            string text = "Scene=" + sc.path + " Missing=" + missing + " Interactables=" + Object.FindObjectsByType<InvestigationInteractable>(FindObjectsSortMode.None).Length + " tool=" + AssetDatabase.GetAssetPath(part.sharedMesh);
            File.WriteAllText("Test/KetQua/investigation_r102/illustration-integration.txt", text);
            if (missing != 0)
                throw new Exception(text);
            r.Log(text);
        }
    }
}

